"""Library-free verifier (standard library only). Checks change.D7_certificates
(i) Pratt and (ii) ECPP step criteria as the held text states them."""
import json, math, sys


def pratt_ok(c):
    q = c["p"]
    if q == 2:
        return True
    prod = 1
    for f, e, sub in c["factors"]:
        prod *= f ** e
        if sub["p"] != f or not pratt_ok(sub):
            return False
    a = c["a"]
    return prod == q - 1 and pow(a, q - 1, q) == 1 and all(pow(a, (q - 1) // f, q) != 1 for f, _, _ in c["factors"])


def ec_mul(k, P, a4, N):
    """Projective-free affine double-and-add mod N; returns None for infinity.
    Raises ValueError if a denominator is not invertible mod N."""
    def add(A, B):
        if A is None:
            return B
        if B is None:
            return A
        (x1, y1), (x2, y2) = A, B
        if (x1 - x2) % N == 0:
            if (y1 + y2) % N == 0:
                return None
            den = 2 * y1 % N
            num = (3 * x1 * x1 + a4) % N
        else:
            den = (x2 - x1) % N
            num = (y2 - y1) % N
        if math.gcd(den, N) != 1:
            raise ValueError("non-invertible")
        lam = num * pow(den, -1, N) % N
        x3 = (lam * lam - x1 - x2) % N
        return (x3, (lam * (x1 - x3) - y1) % N)
    R, Q = None, P
    while k:
        if k & 1:
            R = add(R, Q)
        Q = add(Q, Q)
        k >>= 1
    return R


def step_ok(st, nxt_N):
    N, t, s, a4, (x, y) = st
    if math.gcd(N, 6) != 1:
        return False, "gcd"
    m = N + 1 - t
    if m % s:
        return False, "s|m"
    q = m // s
    b = (y * y - x ** 3 - a4 * x) % N
    if math.gcd((4 * a4 ** 3 + 27 * b * b) % N, N) != 1:
        return False, "disc"
    try:
        if ec_mul(m, (x, y), a4, N) is not None:
            return False, "[m]P"
        sP = ec_mul(s, (x, y), a4, N)
    except ValueError:
        return False, "noninv"
    if sP is None:
        return False, "[s]P infinity"
    c = math.isqrt(math.isqrt(N))
    while c ** 4 < N:
        c += 1
    while c > 0 and (c - 1) ** 4 >= N:
        c -= 1
    if not q > (c + 1) ** 2:
        return False, "q bound"
    if nxt_N is not None and nxt_N != q:
        return False, "chain"
    return True, q


d = json.load(open(sys.argv[1]))
steps = d["ecpp"]
assert steps[0][0] == d["N"]
res = []
for i, st in enumerate(steps):
    ok, info = step_ok(st, steps[i + 1][0] if i + 1 < len(steps) else None)
    res.append(ok)
    if not ok:
        print(json.dumps({"verdict": "reject", "step": i, "why": info}))
        sys.exit(1)
tq = info
assert tq == d["terminal_q"] and d["terminal_pratt"]["p"] == tq
ok = pratt_ok(d["terminal_pratt"])
print(json.dumps({"verdict": "accept" if ok else "reject", "N_bits": d["N"].bit_length(), "steps": len(steps),
                  "terminal_q_bits": tq.bit_length(), "terminal_pratt": ok,
                  "modules_loaded_nonstdlib": sorted(m for m in sys.modules if m.split(".")[0] not in sys.stdlib_module_names)}))

