"""NJ1 review computation (TASK-20260927-10c752). Independent implementation of
the held parse rules as amended by span EIP-R, FP-DEF and C-FIELD cases_extracted.
Zero runs. Integers are emitted as bits + sha256(decimal) in the summary; decimal
values go only to the private sidecar used for the NJ5/FP comparisons.
"""
import hashlib, json, math, re, sys

import cypari2

pari = cypari2.Pari(size=2**27, sizemax=2**32)
REPO = sys.argv[1]
SRC = sys.argv[2]
SPEC = REPO + "/inputs/SAFECURVES-20260825/specs/"
WS = "\t\n\x0b\x0c\r \x85\xa0"
HEX = set("0123456789abcdefABCDEF")
DEC = set("0123456789")


def enc(n):
    return {"bits": abs(n).bit_length(), "sha256_dec": hashlib.sha256(str(abs(n)).encode()).hexdigest(),
            "sign": "-" if n < 0 else "+"}


def read_lines(path):
    t = open(path, "rb").read().decode("utf-8", errors="strict")
    return t, t.split("\n")


def strip(s):
    return s.strip(WS)


def rmws(s):
    return "".join(c for c in s if c not in WS and c != "\\")


PRINTED = {}


class LocFail(Exception):
    pass


def block(lines, start_pred, end_pred):
    i0 = next((i for i, l in enumerate(lines) if start_pred(l)), None)
    if i0 is None:
        raise LocFail("block start not found")
    i1 = next((j for j in range(i0 + 1, len(lines)) if end_pred(lines[j])), len(lines))
    return i0, i1


# ---------------- PR-SP800
SEC_RE = re.compile(r"^[0-9]+(\.[0-9]+)*\.$")
LAB_RE = re.compile(r"^[A-Za-z]{1,4}:")


def pr_sp800(lines, section, L):
    i0, i1 = block(lines, lambda l: strip(l) == section, lambda l: SEC_RE.match(strip(l)) is not None)
    li = next((i for i in range(i0, i1) if lines[i].lstrip(WS).startswith(L + ":")), None)
    if li is None:
        raise LocFail("label line %s not found" % L)
    rec = {"block_first_line": i0 + 1, "block_last_line": i1, "label_line": li + 1}
    # text of the block from the char after "L:" on the label line
    line = lines[li]
    k = line.index(L + ":", len(line) - len(line.lstrip(WS))) + 2
    # (b): start of next line in block whose stripped content matches LAB_RE
    nb = next((j for j in range(li + 1, i1) if LAB_RE.match(strip(lines[j]))), None)
    tail_lines = [line[k:]] + lines[li + 1:(nb if nb is not None else i1)]
    tail = "\n".join(tail_lines)
    pa = tail.find("(")
    ended_by_a = pa != -1
    span = tail[:pa] if ended_by_a else tail
    dec = rmws(span)
    dec_clean = bool(dec) and set(dec) <= DEC
    rec["decimal_form"] = "clean" if dec_clean else "contaminated"
    hexv = None
    if ended_by_a:
        # hex form: after "(" with ws removed, next three chars "=0x"
        # search beyond the (b) bound for ")"? The span of the hex form runs to the first ")" after "=0x".
        rest_full = "\n".join([line[k:]] + lines[li + 1:i1])
        after = rest_full[rest_full.find("(") + 1:]
        after_nows = rmws(after)
        if after_nows.startswith("=0x"):
            # locate "=0x" in raw text
            idx0 = 0
            seen = ""
            for idx0, ch in enumerate(after):
                if ch in WS or ch == "\\":
                    continue
                seen += ch
                if seen == "=0x":
                    break
            close = after.find(")", idx0 + 1)
            h = rmws(after[idx0 + 1: close if close != -1 else len(after)])
            if close != -1 and h and set(h) <= HEX:
                hexv = int(h, 16)
                PRINTED[(section, L)] = h.lower()
                rec["hex_form"] = "clean"
            else:
                rec["hex_form"] = "contaminated"
        else:
            rec["hex_form"] = "absent"
    else:
        rec["hex_form"] = "absent"
    if hexv is not None:
        rec["representation"] = "hex"
        if dec_clean:
            if len(dec) == len(str(hexv)):
                rec["decimal_compared"] = "equal" if int(dec) == hexv else "MISMATCH"
                if int(dec) != hexv:
                    raise LocFail("decimal/hex mismatch")
            else:
                rec["decimal_compared"] = "decimal_span_not_a_literal"
        return hexv, rec, (dec if False else None)
    if dec_clean:
        rec["representation"] = "decimal"
        PRINTED[(section, L)] = dec
        return int(dec), rec, None
    raise LocFail("neither form clean")


# ---------------- PR-SEC2
def pr_sec2(lines, curve, L):
    rx = re.compile(r"^[0-9]+(\.[0-9]+)+RecommendedParameters" + re.escape(curve) + r"$")
    i0, i1 = block(lines, lambda l: rx.match(rmws(l)) is not None, lambda l: "RecommendedParameters" in l)
    li = None
    for i in range(i0, i1):
        if strip(lines[i]) == L:
            nxt = next((j for j in range(i + 1, i1) if strip(lines[j]) != ""), None)
            if nxt is not None and lines[nxt].lstrip(WS).startswith("="):
                li, eq = i, nxt
                break
    if li is None:
        raise LocFail("sec2 label %s" % L)
    rest = rmws(lines[eq].lstrip(WS)[1:])
    vals = []
    if rest:
        first, j = rest, eq + 1
    else:
        fj = next((j for j in range(eq + 1, i1) if strip(lines[j]) != ""), None)
        if fj is None:
            raise LocFail("no value line")
        first, j = rmws(lines[fj]), fj + 1
    if not first or not set(first) <= HEX:
        raise LocFail("first value line not hex")
    vals.append(first)
    while j < i1:
        c = rmws(lines[j])
        if c and set(c) <= HEX and len(c) >= 4:
            vals.append(c)
            j += 1
        else:
            break
    PRINTED[(curve, L)] = "".join(vals).lower()
    return int("".join(vals), 16), {"block_first_line": i0 + 1, "label_line": li + 1, "value_lines": len(vals),
                                    "representation": "hex"}


# ---------------- PR-RFC5639
RFC_SEC = re.compile(r"^[0-9]+(\.[0-9]+)*\.\s")


def pr_rfc5639(lines, curve, L):
    i0, i1 = block(lines, lambda l: strip(l) == "Curve-ID: " + curve,
                   lambda l: strip(l).startswith("Curve-ID:") or strip(l).startswith("#Twisted")
                   or RFC_SEC.match(strip(l)) is not None)
    li = next((i for i in range(i0, i1) if strip(lines[i]).startswith(L + " =") or strip(lines[i]) == L + " ="), None)
    if li is None:
        raise LocFail("rfc5639 label")
    parts = [lines[li][lines[li].index("=") + 1:]]
    j = li + 1
    while j < len(lines):
        s = strip(lines[j])
        if s and set(rmws(s)) <= HEX:
            parts.append(s)
            j += 1
        else:
            break
    v = rmws("".join(parts))
    if not v or not set(v) <= HEX:
        raise LocFail("rfc5639 value")
    return int(v, 16), {"block_first_line": i0 + 1, "label_line": li + 1, "representation": "hex"}


# ---------------- PR-RFC7748
def pr_rfc7748(lines, L):
    i0, i1 = block(lines, lambda l: strip(l) == "4.1.  Curve25519", lambda l: RFC_SEC.match(strip(l)) is not None)
    li = next((i for i in range(i0 + 1, i1) if re.match(re.escape(L) + "[" + re.escape(WS) + "]", strip(lines[i]))), None)
    if li is None:
        raise LocFail("rfc7748 label")
    rem = rmws(strip(lines[li])[len(L):])
    m1 = re.fullmatch(r"2\^([0-9]+)\+0x([0-9A-Fa-f]+)", rem)
    m2 = re.fullmatch(r"2\^([0-9]+)-([0-9]+)", rem)
    if m1:
        return 2 ** int(m1.group(1)) + int(m1.group(2), 16), {"label_line": li + 1, "form": "2^E + 0xH"}
    if m2:
        return 2 ** int(m2.group(1)) - int(m2.group(2)), {"label_line": li + 1, "form": "2^E - S"}
    raise LocFail("rfc7748 form")


# ---------------- PR-IETF-DRAFT
def pr_ietf(lines, L):
    i0, i1 = block(lines, lambda l: re.match(r"^[0-9]+(\.[0-9]+)*\.\s.*\(BLS12-381\)$", strip(l)) is not None,
                   lambda l: RFC_SEC.match(strip(l)) is not None)
    li = None
    for i in range(i0, i1):
        s = strip(lines[i])
        if s.startswith("*"):
            s = s[1:].lstrip(WS)
        if re.match("^" + L + r"\s*[:=]", s):
            li = i
            break
    if li is None:
        raise LocFail("ietf label")
    s = lines[li]
    cut = min([x for x in (s.find(":"), s.find("=")) if x != -1])
    parts = [s[cut + 1:]]
    allowed = re.compile(r"^(0x|x|\^|\+|-|[0-9A-Fa-f]|[" + re.escape(WS) + "])+$")
    j = li + 1
    while j < i1:
        t = strip(lines[j])
        if t and allowed.match(t):
            parts.append(t)
            j += 1
        else:
            break
    v = rmws("".join(parts))
    if re.fullmatch(r"-?0x[0-9A-Fa-f]+", v):
        n = int(v.replace("0x", ""), 16) if not v.startswith("-") else -int(v[3:], 16)
        form = "hex"
    elif re.fullmatch(r"-?[0-9]+", v):
        n, form = int(v), "decimal"
    elif re.fullmatch(r"-?2\^[0-9]+([+-]2\^[0-9]+)*", v):
        n = 0
        for sg, e in re.findall(r"([+-]?)2\^([0-9]+)", v):
            n += (-1 if sg == "-" else 1) * 2 ** int(e)
        form = "powers_of_two"
    else:
        raise LocFail("ietf value form: " + v[:30])
    return n, {"block_first_line": i0 + 1, "label_line": li + 1, "form": form}


# ---------------- PR-EIP197 (corrected r via span EIP-R; held p)
EIP_R_CORRECTED = r"prime order `q\s*=\s*([0-9]+)`"
EIP_R_HELD = r"prime order q\s*=\s*([0-9]+)"
EIP_P_HELD = r"(?<![A-Za-z0-9_])p\s*=\s*([0-9]+)"


def pr_eip197(text):
    rc = list(re.finditer(EIP_R_CORRECTED, text))
    rh = list(re.finditer(EIP_R_HELD, text))
    ph = list(re.finditer(EIP_P_HELD, text))
    rec = {"corrected_r_match_count": len(rc), "held_r_match_count": len(rh), "held_p_match_count": len(ph)}
    if len(rc) != 1:
        raise LocFail("EIP-R match count %d" % len(rc))
    if not ph:
        raise LocFail("p no match")
    rec["r_line"] = text[:rc[0].start()].count("\n") + 1
    rec["p_line"] = text[:ph[0].start()].count("\n") + 1
    # tolerance probe: does any variant tolerant of other chars (e.g. no backticks, or backticks optional) match more?
    rec["variant_backticks_optional_count"] = len(re.findall(r"prime order `?q\s*=\s*([0-9]+)`?", text))
    rec["r_context"] = text[max(0, rc[0].start() - 40):rc[0].start()].replace("\n", "\\n")
    return int(rc[0].group(1)), int(ph[0].group(1)), rec


def iroot_poly(p, coeffs):
    """Find integer u (possibly negative) with poly(u) == p, poly increasing for u >= 0 and |u| large."""
    f = lambda u: sum(c * u ** k for k, c in enumerate(coeffs))
    for sign in (1, -1):
        lo, hi = 0, 1
        while f(sign * hi) < p:
            hi *= 2
            if hi > 2 ** 200:
                break
        while lo < hi:
            mid = (lo + hi) // 2
            if f(sign * mid) < p:
                lo = mid + 1
            else:
                hi = mid
        if f(sign * lo) == p:
            return sign * lo
    return None


def isprime(n):
    return bool(pari.isprime(n))


out = {"rows": {}, "checks": {}, "failures": {}}
priv = {}
sp_text, sp = read_lines(SPEC + "sp800-186.txt")
s2_text, s2 = read_lines(SPEC + "sec2-v2.txt")
b_text, b = read_lines(SPEC + "rfc5639.txt")
x_text, x = read_lines(SPEC + "rfc7748.txt")
e_text, e = read_lines(SRC + "/eip-197.md")
d_text, d = read_lines(SRC + "/draft-irtf-cfrg-pairing-friendly-curves-14.txt")

ROWS = [("NIST-P-224", "3.2.1.2.", "secp224r1"), ("NIST-P-256", "3.2.1.3.", "secp256r1"),
        ("NIST-P-384", "3.2.1.4.", "secp384r1"), ("NIST-P-521", "3.2.1.5.", "secp521r1")]
vals = {}


def put(row, lab, fn):
    try:
        v, rec = fn()[:2]
        vals[(row, lab)] = v
        out["rows"].setdefault(row, {})[lab] = dict(rec, **enc(v))
    except LocFail as ex:
        out["failures"]["%s:%s" % (row, lab)] = str(ex)


for row, sec, sc in ROWS:
    for L, lab in (("n", "r"), ("p", "p"), ("h", "h")):
        put(row, lab, lambda: pr_sp800(sp, sec, L))
    put(row, "cross_source_n", lambda: pr_sec2(s2, sc, "n"))
for L, lab in (("n", "r"), ("p", "p"), ("h", "h")):
    put("secp256k1", lab, lambda: pr_sec2(s2, "secp256k1", L))
for c in ("brainpoolP256r1", "brainpoolP384r1"):
    for L, lab in (("q", "r"), ("p", "p"), ("h", "h")):
        put(c, lab, lambda: pr_rfc5639(b, c, L))
for L, lab in (("n", "r"), ("p", "p"), ("h", "h")):
    put("Ed25519-L", lab, lambda: pr_sp800(sp, "3.2.3.1.", L))
put("Ed25519-L", "cross_source_order", lambda: pr_rfc7748(x, "order"))
put("Ed25519-L", "rfc7748_p", lambda: pr_rfc7748(x, "p"))
try:
    r_bn, p_bn, rec = pr_eip197(e_text)
    vals[("BN254-r", "r")], vals[("BN254-r", "p")] = r_bn, p_bn
    out["rows"]["BN254-r"] = {"r": enc(r_bn), "p": enc(p_bn), "locator": rec}
except LocFail as ex:
    out["failures"]["BN254-r"] = str(ex)
for L, lab in (("p", "p"), ("r", "r"), ("h", "h"), ("t", "t")):
    put("BLS12-381-r", lab, lambda: pr_ietf(d, L))

# cross-checks
ck = out["checks"]
for row, _, _ in ROWS:
    ck[row + ":sec2_n_equals_sp800_n"] = vals.get((row, "cross_source_n")) == vals.get((row, "r"))
ck["Ed25519-L:rfc7748_order_equals_sp800_n"] = vals.get(("Ed25519-L", "cross_source_order")) == vals.get(("Ed25519-L", "r"))
import yaml  # noqa: E402
spec = yaml.safe_load(open(REPO + "/experiments/EXP-AUXIN-7e2e3d/specification.yaml"))
for r in spec["experiment"]["inputs"]["parameters"]["frozen_curve_list"]:
    if "r_hex_pinned_internal" in r:
        ck[r["id"] + ":internal_consistency_r_hex_pinned_internal"] = int(str(r["r_hex_pinned_internal"]).replace(" ", ""), 16) == vals.get((r["id"], "r"))
if ("BN254-r", "p") in vals:
    u = iroot_poly(vals[("BN254-r", "p")], [1, 6, 24, 36, 36])
    ck["BN254-r:family_u_found"] = u is not None
    ck["BN254-r:family_check"] = u is not None and vals[("BN254-r", "r")] == 36 * u ** 4 + 36 * u ** 3 + 18 * u ** 2 + 6 * u + 1
    if u is not None:
        ck["BN254-r:family_u"] = enc(u)
tt = vals.get(("BLS12-381-r", "t"))
if tt is not None:
    rr = tt ** 4 - tt ** 2 + 1
    num = (tt - 1) ** 2 * rr
    ck["BLS12-381-r:family_check"] = (vals[("BLS12-381-r", "r")] == rr and num % 3 == 0
                                      and vals[("BLS12-381-r", "p")] == num // 3 + tt)
CF1 = 2 ** 255 - 19
CF2 = 2 ** 256 - 2 ** 224 + 2 ** 192 + 2 ** 96 - 1
ck["CF-1_equals_Ed25519-L_extracted_p"] = vals.get(("Ed25519-L", "p")) == CF1
ck["CF-2_equals_NIST-P-256_extracted_p"] = vals.get(("NIST-P-256", "p")) == CF2

ROWIDS = ["NIST-P-224", "NIST-P-256", "NIST-P-384", "NIST-P-521", "secp256k1", "brainpoolP256r1",
          "brainpoolP384r1", "Ed25519-L", "BN254-r", "BLS12-381-r"]
FP = {vals[(rid, "p")] for rid in ROWIDS if (rid, "p") in vals}
MFP = {CF1, CF2}
HELD_FP = FP | MFP


def confounder(cand, fp, h=None, p=None, clause1=True):
    reasons = []
    if clause1 and cand in fp:
        reasons.append("field_prime")
    if not isprime(cand):
        reasons.append("not_prime")
    if h is not None:
        if abs(p + 1 - h * cand) > 2 * math.isqrt(p) + 2:
            reasons.append("hasse")
    return reasons


fpres = {"distinct_extracted_field_primes": len(FP), "rows_with_extracted_field_prime": sum((rid, "p") in vals for rid in ROWIDS),
         "corrected_FP_equals_held_FP": FP == HELD_FP, "CF-1_in_corrected_FP": CF1 in FP, "CF-2_in_corrected_FP": CF2 in FP}
# cases_extracted under corrected FP, M-FP, and corrected-minus-one
ce = {}
for rid in ROWIDS:
    pv = vals[(rid, "p")]
    ce[rid] = {"corrected": confounder(pv, FP), "M-FP": confounder(pv, MFP),
               "corrected_minus_own": confounder(pv, FP - {pv})}
fpres["cases_extracted"] = ce
fpres["gate_passes_corrected"] = all(v["corrected"] == ["field_prime"] for v in ce.values())
fpres["gate_fails_under_M-FP_rows"] = [rid for rid, v in ce.items() if v["M-FP"] != ["field_prime"]]
fpres["gate_fails_under_corrected_minus_one_rows"] = [rid for rid, v in ce.items() if v["corrected_minus_own"] != ["field_prime"]]
# closed-form C-FIELD and mutation
fpres["CF-1_corrected"] = confounder(CF1, FP, h=vals[("Ed25519-L", "h")], p=vals[("Ed25519-L", "p")])
fpres["CF-2_corrected"] = confounder(CF2, FP, h=vals[("NIST-P-256", "h")], p=vals[("NIST-P-256", "p")])
fpres["CF-1_mutation"] = confounder(CF1, FP, h=vals[("Ed25519-L", "h")], p=vals[("Ed25519-L", "p")], clause1=False)
fpres["CF-2_mutation"] = confounder(CF2, FP, h=vals[("NIST-P-256", "h")], p=vals[("NIST-P-256", "p")], clause1=False)
# alternative reading probe: hasse applied to CF-X-<row> with that row's printed h
alt = {}
for rid in ROWIDS:
    if (rid, "h") in vals:
        alt[rid] = confounder(vals[(rid, "p")], FP, h=vals[(rid, "h")], p=vals[(rid, "p")])
fpres["ALT_reading_hasse_applied_to_cases_extracted"] = alt
# C-FIELD primes substituted for r of their rows (deployed-row confounder with the row's own p, h)
sub = {}
for tag, val, rid in (("CF-1_as_r_of_Ed25519-L", CF1, "Ed25519-L"), ("CF-2_as_r_of_NIST-P-256", CF2, "NIST-P-256")):
    sub[tag] = confounder(val, FP, h=vals[(rid, "h")], p=vals[(rid, "p")])
fpres["C-FIELD_substituted_for_r"] = sub
# PTM-B: brainpoolP384r1 p presented as r of its row
bp = vals[("brainpoolP384r1", "p")]
fpres["PTM-B_like_bp384_p_as_r_corrected"] = confounder(bp, FP, h=vals[("brainpoolP384r1", "h")], p=bp)
fpres["PTM-B_like_bp384_p_as_r_under_M-FP"] = confounder(bp, MFP, h=vals[("brainpoolP384r1", "h")], p=bp)
# deployed rows
dep = {}
for rid in ROWIDS:
    h = vals.get((rid, "h"))
    dep[rid] = confounder(vals[(rid, "r")], FP, h=h, p=vals[(rid, "p")] if h is not None else None)
fpres["deployed_confounder_reasons"] = dep
fpres["deployed_r_in_FP"] = [rid for rid in ROWIDS if vals[(rid, "r")] in FP]
out["fp"] = fpres
out["bit_classes"] = sorted({vals[(rid, "r")].bit_length() for rid in ROWIDS})
out["bit_classes_without_BN254-r"] = sorted({vals[(rid, "r")].bit_length() for rid in ROWIDS if rid != "BN254-r"})
print(json.dumps(out, indent=1, sort_keys=True))
